static int minutesToSeconds(int minutes) {
    return Math.multiplyExact(minutes, 60);
}

static int tripDuration(int hours, int extraMinutes) {
    int totalMinutes = Math.addExact(Math.multiplyExact(hours, 60), extraMinutes);
    return minutesToSeconds(totalMinutes);
}

