final class Thermostat {
    private final String room;
    private int targetCelsius;

    Thermostat(String room, int targetCelsius) {
        if (room == null || room.isBlank() || targetCelsius < 5 || targetCelsius > 35) {
            throw new IllegalArgumentException("invalid thermostat state");
        }
        this.room = room;
        this.targetCelsius = targetCelsius;
    }

    boolean setTarget(int next) {
        if (next < 5 || next > 35) return false;
        targetCelsius = next;
        return true;
    }
}
